/**
 * @file swedishExampleNormalizer.ts
 * @description Generates natural, A1-friendly bilingual example sentences for
 *              Swedish vocabulary entries. Uses category + part-of-speech aware
 *              templates with deterministic per-word rotation so learners see
 *              varied, contextual examples instead of robotic auto-generated
 *              ones. Manually curated examples (non-generic) are preserved.
 * @copyright 2026 HaiEduTech, ILC. All rights reserved.
 */
import type { SwedishWord } from "./swedishVocabBank";

/* --------------------------- detection helpers --------------------------- */

const GENERIC_SV = [
  /^Jag gillar /,
  /^Jag vill /,
  /^Det är /,
  /^Hon arbetar /,
  /^Jag har \S+ vänner\./,
  /^Ordet ['"].+?['"] betyder /,
  /^(Verbet|Adjektivet|Adverbet|Uttrycket|Bindeordet|Prepositionen|Pronomenet|Talet) ['"]/,
];

const AWKWARD_EN = [
  /\bI want to (can|must|want|need|will|may|shall)\b/i,
  /\bI like (face|arm|shoulder|leg|finger|foot|throat|hand|head|hair|knee|stomach|mouth|nose|back|tooth|eye|ear)\b/i,
  /\bShe works (everyone|everything|also|to the right|to the left|straight ahead)\b/i,
  /\bIt is (old|new|clean|dirty|fast|slow|early|late)\b/i,
  /\bThe (verb|adjective|adverb|phrase|conjunction|preposition|pronoun|number|word) ['"]/i,
];

const AWKWARD_VI = [
  /Tôi muốn (có thể|phải|muốn|cần|sẽ)\.?$/i,
  /Cô ấy làm việc (tất cả|cũng|sang phải|sang trái|đi thẳng)\.?$/i,
  /Nó (cũ|mới|sạch|bẩn|nhanh|chậm|sớm|muộn)\.?$/i,
  /^(Động từ|Tính từ|Trạng từ|Cụm từ|Liên từ|Giới từ|Đại từ|Số|Từ) ['"]/i,
];

function isAutoGenerated(word: SwedishWord): boolean {
  const sv = (word.example || "").trim();
  const en = (word.exampleEn || "").trim();
  const vi = (word.exampleVi || "").trim();
  return (
    GENERIC_SV.some((r) => r.test(sv)) ||
    AWKWARD_EN.some((r) => r.test(en)) ||
    AWKWARD_VI.some((r) => r.test(vi))
  );
}

/* ------------------------------- utilities ------------------------------- */

const clean = (v: string) => (v || "").replace(/["“”]/g, "'").trim();

function hash(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function pick<T>(arr: T[], seed: string): T {
  return arr[hash(seed) % arr.length];
}

function cap(s: string): string {
  return s.charAt(0).toUpperCase() + s.slice(1);
}

function stripTo(s: string): string {
  return s.replace(/^to\s+/i, "");
}

/* -------------------------- template definitions ------------------------- */

