/* --------------------------- article helpers ----------------------------- */

function artSV(word: SwedishWord): { full: string; capWord: string } {
  const a = word.article;
  if (a === "en") return { full: "en ", capWord: "En " };
  if (a === "ett") return { full: "ett ", capWord: "Ett " };
  return { full: "", capWord: "" };
}

function artVI(word: SwedishWord): { full: string; capWord: string } {
  if (word.article) return { full: "một ", capWord: "Một " };
  return { full: "", capWord: "" };
}

function artEN(en: string): { full: string; capWord: string } {
  const word = stripTo(en).trim();
  if (!word) return { full: "", capWord: "" };
  const useAn = /^[aeiouAEIOU]/.test(word);
  return useAn
    ? { full: "an ", capWord: "An " }
    : { full: "a ", capWord: "A " };
}

function fill(tmpl: Tmpl, w: SwedishWord): Tmpl {
  const W = clean(w.sv);
  const VI = clean(w.vi);
  const EN = stripTo(clean(w.en));
  const aSV = artSV(w);
  const aVI = artVI(w);
  const aEN = artEN(w.en);

  const replaceAll = (str: string, find: string, repl: string) =>
    str.split(find).join(repl);

  const sub = (s: string) => {
    let r = s;
    r = replaceAll(r, "{ART_C}", aSV.capWord);
    r = replaceAll(r, "{ART}", aSV.full);
    r = replaceAll(r, "{ARTVI_C}", aVI.capWord);
    r = replaceAll(r, "{ARTVI}", aVI.full);
    r = replaceAll(r, "{ARTEN}", aEN.full);
    r = replaceAll(r, "{W_C}", cap(W));
    r = replaceAll(r, "{W}", W);
    r = replaceAll(r, "{VI_C}", cap(VI));
    r = replaceAll(r, "{VI}", VI);
    r = replaceAll(r, "{EN_C}", cap(EN));
    r = replaceAll(r, "{EN}", EN);
    return r;
  };

  return { sv: sub(tmpl.sv), vi: sub(tmpl.vi), en: sub(tmpl.en) };
}

/* ------------------------ main normalization ----------------------------- */

function templatesFor(word: SwedishWord): Tmpl[] {
  const pos = word.pos.toLowerCase();
  if (pos.startsWith("v")) return VERB_TEMPLATES;
  if (pos.startsWith("adj")) return ADJ_TEMPLATES;
  if (pos.startsWith("adv")) return ADV_TEMPLATES;
  if (pos.startsWith("prep")) return PREP_TEMPLATES;
  if (pos.startsWith("conj")) return CONJ_TEMPLATES;
  // nouns, phrases, pronouns, numerals → noun-style by category
  const cat = (word.category || "default").toLowerCase();
  return NOUN_TEMPLATES[cat] || NOUN_TEMPLATES.default;
}

/** IDs of entries with hand-curated examples — preserved as-is. */
const CURATED_IDS = new Set<string>([
  "m802", "m751", "m750", "m706", "m356", "m24", "m77", "mm646", "mm641",
]);

// Exposed for potential future QA tooling.
export { isAutoGenerated };

export function normalizeSwedishWordExamples(word: SwedishWord): SwedishWord {
  if (CURATED_IDS.has(word.id)) return word;

  const tmpls = templatesFor(word);
  const chosen = pick(tmpls, `${word.id}|${word.sv}`);
  const filled = fill(chosen, word);

  return {
    ...word,
    example: filled.sv,
    exampleVi: filled.vi,
    exampleEn: filled.en,
  };
}
